#!/usr/bin/env python3
from pathlib import Path
import base64, io, tarfile, sys, xml.etree.ElementTree as ET
root=Path(sys.argv[1]).resolve()
A='{http://schemas.android.com/apk/res/android}'
checks=[]
def require(c,m):
    if not c: raise AssertionError(m)
    checks.append('PASS: '+m)
car=root/'fermata/src/auto/AndroidManifest.xml'
old=ET.fromstring(car.read_text())
old_perms=sorted(ET.tostring(e) for e in old if e.tag.startswith('uses-permission'))
payload=base64.b64decode('[... ELLIPSIZATION ...]')
with tarfile.open(fileobj=io.BytesIO(payload), mode='r:gz') as tf:
    for member in tf.getmembers():
        dst=(root/member.name).resolve()
        require(str(dst).startswith(str(root)+str(Path('/'))), 'safe v4 path: '+member.name)
        dst.parent.mkdir(parents=True,exist_ok=True)
        with tf.extractfile(member) as src: dst.write_bytes(src.read())
new=ET.fromstring(car.read_text())
require(old_perms==sorted(ET.tostring(e) for e in new if e.tag.startswith('uses-permission')), 'no new Android Auto manifest permissions')
manifest=car.read_text()
require('MediaServiceStarter' not in manifest, 'Bluetooth auto-start receiver removed')
proj=(root/'fermata/src/auto/java/me/aap/fermata/auto/ProjectionActivity.java').read_text()
require('createConfigForDefaultDisplay' in proj, 'full-display MediaProjection request retained')
prefs=(root/'fermata/src/main/java/me/aap/fermata/ui/activity/MainActivityPrefs.java').read_text()
require('RONAN_HIDE_PHONE_NAV", true' in prefs, 'phone navigation trim enabled by default')
require('RONAN_HIDE_PHONE_STATUS", false' in prefs, 'status-bar trim remains optional')
require('RONAN_DESKTOP_MODE", false' in prefs, 'DeX-style Ronan Desktop remains opt-in')
require('RONAN_ALLOW_ROOT", false' in prefs, 'root remains disabled by default')
renderer=(root/'fermata/src/auto/java/me/aap/fermata/auto/AdaptiveMirrorRenderer.java').read_text()
require('uniform vec4 uCrop' in renderer and 'cropBottom' in renderer, 'GPU crop path included')
mirror=(root/'fermata/src/auto/java/me/aap/fermata/auto/MirrorDisplay.java').read_text()
require('m.sourceY' in mirror and 'applyCrop(renderer)' in mirror, 'cropped touch coordinates remapped')
launcher=(root/'fermata/src/auto/java/me/aap/fermata/auto/LauncherActivity.java').read_text()
require('RONAN DESKTOP' in launcher and 'TextClock' in launcher, 'Ronan Desktop launcher included')
hub=(root/'fermata/src/main/java/me/aap/fermata/ui/activity/RonanHubActivity.java').read_text()
require('MANUAL ACTIVATION' in hub and 'Trim phone navigation buttons' in hub, 'manual activation and system-bar controls exposed')
versions=(root/'gradle/libs.versions.toml').read_text()
require('appVersionCode = "4"' in versions and 'appVersionName = "1.2.0-test4"' in versions, 'version bumped to test4')
(root/'RONAN-V4-SOURCE-CHECKS.txt').write_text('\n'.join(checks)+'\n')
print('\n'.join(checks))
